const path = require("path");
const { ScalekitClient } = require("@scalekit-sdk/node");

const REQUIRED_ENV_VARS = [
  "SCALEKIT_ENV_URL",
  "SCALEKIT_CLIENT_ID",
  "SCALEKIT_CLIENT_SECRET",
];

const ORG_NAME = "Harbor Test Org";
const ORG_ID_PATH = "/home/user/scalekit-orgs/org_id.txt";
const TRIAL_ID_PATH = "/logs/trial_id";

const loadTrialId = async () => {
  const raw = await fs.readFile(TRIAL_ID_PATH, "utf8");
  return raw.trim();
};

const assertEnv = () => {
  const missing = REQUIRED_ENV_VARS.filter((key) => !process.env[key]);
  if (missing.length) {
    throw new Error(
      "Missing required environment variables: " + missing.join(", ")
    );
  }
};

const listAllOrganizations = async (scalekitClient) => {
  const organizations = [];
  let pageToken;

  do {
    const response = await scalekitClient.organization.listOrganization({
      pageSize: 100,
      ...(pageToken ? { pageToken } : {}),
    });

    if (response?.organizations?.length) {
      organizations.push(...response.organizations);
    }

    pageToken = response?.nextPageToken;
  } while (pageToken);

  return organizations;
};

