const listAllOrganizations = async (scalekitClient) => {
  const organizations = [];
  let pageToken;

  do {
    const response = await scalekitClient.organization.listOrganization({
      pageSize: 100,
      ...(pageToken ? { pageToken } : {}),
    });

    if (response?.organizations?.length) {
      organizations.push(...response.organizations);
    }

    pageToken = response?.nextPageToken;
  } while (pageToken);

  return organizations;
};

