};

const main = async () => {
  assertEnv();

  const trialId = await loadTrialId();
  const externalId = `ext_org_${trialId}`;

  const scalekitClient = new ScalekitClient(
    process.env.SCALEKIT_ENV_URL,
    process.env.SCALEKIT_CLIENT_ID,
    process.env.SCALEKIT_CLIENT_SECRET
  );

  const created = await scalekitClient.organization.createOrganization(ORG_NAME, {
    externalId,
  });

  const createdOrgId = created?.organization?.id;
  if (!createdOrgId) {
    throw new Error("Failed to create organization - missing organization ID.");
  }

  const organizations = await listAllOrganizations(scalekitClient);
  const matchedOrg = organizations.find(
    (org) =>
      org.id === createdOrgId ||
      org.externalId === externalId ||
      org.displayName === ORG_NAME
  );

  if (!matchedOrg) {
    throw new Error("Created organization was not found in organization list.");
  }

  await fs.writeFile(ORG_ID_PATH, matchedOrg.id, "utf8");

  console.log("Created organization ID:", matchedOrg.id);
};

main().catch((error) => {
  console.error("Error managing Scalekit organizations:", error.message);
  process.exitCode = 1;
});
